#!/usr/bin/env node
/**
 * Bundles @quieto/ui into a single browser-loadable module for the docs site.
 *
 * The library itself publishes unbundled ESM with bare specifiers
 * (`import { html } from 'lit'`), which is correct for a package that consumers
 * bundle themselves — but a browser cannot resolve a bare specifier, so loading
 * `dist/index.js` directly leaves every element un-upgraded. The page still shows
 * the server-rendered markup, which is the confusing part: it *looks* right and is
 * completely inert.
 *
 * Bundling here rather than adding an import map keeps this to one file, instead
 * of hand-maintaining entries for lit's whole internal module graph.
 */

import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';

import * as esbuild from 'esbuild';

const HERE = dirname(new URL(import.meta.url).pathname);
const OUT = join(HERE, 'src/assets/ui.js');

await mkdir(dirname(OUT), { recursive: true });

const result = await esbuild.build({
  entryPoints: [join(HERE, 'client.js')],
  outfile: OUT,
  bundle: true,
  format: 'esm',
  target: 'es2022',
  minify: true,
  sourcemap: true,
  // Lit's dev-mode warning is noisy in a docs site and the check for it is what
  // prints "Lit is in dev mode" on every page load.
  define: { 'process.env.NODE_ENV': '"production"' },
  metafile: true,
  legalComments: 'none',
  banner: {
    js: '/* @quieto/ui — bundled for the docs site. Generated by bundle-components.js; do not edit. */',
  },
});

const bytes = Object.values(result.metafile.outputs).find((output) => output.entryPoint)?.bytes ?? 0;
console.log(`✓ bundled @quieto/ui → src/assets/ui.js (${(bytes / 1024).toFixed(1)} kB minified)`);

if (result.warnings.length > 0) {
  console.warn(result.warnings);
}

// ── Canaries ────────────────────────────────────────────────────────────────
// Every failure mode this file guards against is silent in the browser: no error,
// no failed request, just markup that never upgrades. So assert on the output.

const { readFile } = await import('node:fs/promises');
const code = await readFile(OUT, 'utf8');

if (/\bfrom\s*["'](?!\.|\/)/.test(code)) {
  const match = code.match(/\bfrom\s*["'][^"']+["']/);
  throw new Error(
    `bundle contains an unresolved bare import (${match?.[0]}), which will not load in a browser`,
  );
}

// Tree shaking can remove the whole library: a side-effect-only
// `import '@quieto/ui'` is dropped unless the package's `sideEffects` field lists
// the module that registers the elements.
for (const tag of ['qds-button', 'qds-stack']) {
  if (!code.includes(tag)) {
    throw new Error(
      `bundle does not contain "${tag}" — the component registration was tree-shaken ` +
        'away. Check the `sideEffects` field in packages/ui/package.json.',
    );
  }
}

if (!code.includes('customElements.define') && !/customElements\)?\.define/.test(code)) {
  throw new Error('bundle contains no customElements.define call — nothing will register');
}

// The hydrate shim must be present, or SSR'd components render twice.
if (!/hydrat/i.test(code)) {
  throw new Error(
    'bundle is missing the Lit hydration support shim — SSR components will render twice',
  );
}
